import calendar
from datetime import date, timedelta

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _add_months(year, month, offset):
    total = year * 12 + (month - 1) + offset
    return total // 12, total % 12 + 1


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    tokens = rule.split(" ")
    kind = tokens[0]
    result = []

    if kind == "DAILY":
        k = int(tokens[1])
        d = s
        while len(result) < count:
            result.append(d.isoformat())
            d += timedelta(days=k)
        return result

    if kind == "WEEKLY":
        k = int(tokens[1])
        days = sorted(_WD[c] for c in tokens[2].split(","))
        monday = s - timedelta(days=s.weekday())
        w = 0
        while len(result) < count:
            base = monday + timedelta(weeks=w)
            for idx in days:
                d = base + timedelta(days=idx)
                if d >= s:
                    result.append(d.isoformat())
                    if len(result) == count:
                        break
            w += k
        return result

    if kind == "MONTHLY":
        k = int(tokens[1])
        m = 0
        while len(result) < count:
            y, mo = _add_months(s.year, s.month, m)
            m += k
            ndays = calendar.monthrange(y, mo)[1]
            if len(tokens) == 3:
                day = int(tokens[2])
                if day == -1:
                    day = ndays
                if day > ndays:
                    continue
            else:
                n = int(tokens[2])
                wd = _WD[tokens[3]]
                if n > 0:
                    first_wd = date(y, mo, 1).weekday()
                    day = 1 + (wd - first_wd) % 7 + 7 * (n - 1)
                    if day > ndays:
                        continue
                else:
                    last_wd = date(y, mo, ndays).weekday()
                    day = ndays - (last_wd - wd) % 7
            d = date(y, mo, day)
            if d >= s:
                result.append(d.isoformat())
        return result

    if kind == "YEARLY":
        k = int(tokens[1])
        mm, dd = map(int, tokens[2].split("-"))
        y = s.year
        while len(result) < count:
            try:
                d = date(y, mm, dd)
            except ValueError:
                d = None
            if d is not None and d >= s:
                result.append(d.isoformat())
            y += k
        return result

    return result
